from collections import deque,Counter
lower=test[9:19,:]
seen=set(); comps=[]
for r in range(lower.shape[0]):
  for c in range(lower.shape[1]):
    if lower[r,c]==1 or (r,c) in seen: continue
    q=deque([(r,c)]); seen.add((r,c)); cells=[]
    while q:
      p=q.popleft(); cells.append(p)
      for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
        np1=(p[0]+dr,p[1]+dc)
        if 0<=np1[0]<lower.shape[0] and 0<=np1[1]<lower.shape[1] and np1 not in seen and lower[np1]!=1:
          seen.add(np1); q.append(np1)
    rmin=min(x[0] for x in cells); cmin=min(x[1] for x in cells)
    mat=np.ones((max(x[0] for x in cells)-rmin+1,max(x[1] for x in cells)-cmin+1),int)*-1
    for rr,cc in cells: mat[rr-rmin,cc-cmin]=lower[rr,cc]
    comps.append({'coords':[(rr+9,cc) for rr,cc in cells], 'mat':mat,'origin':(rmin+9,cmin),'area':len(cells)})
for i,x in enumerate(comps): print(i,x['origin'],'area',x['area'],'shape',x['mat'].shape,'vals',Counter(x['mat'][x['mat']!=-1]),'\n',x['mat'])

mask=set(map(tuple,np.argwhere(test[:8,:]==1)))
# type labels, dimensions
piece_types={'checker4x3':(4,3,1),'square4':(2,2,2),'mixed3x2':(3,2,2),'bar6':(3,1,1),'block2x6':(6,2,1),'pattern4x2':(4,2,1),'bar9':(2,1,4),'zero':(1,1,3)}
# make placements per type
placements={}
for name,(h,w,n) in piece_types.items():
  ps=[]
  for r in range(8-h+1):
    for c in range(20-w+1):
      cells=frozenset((rr,cc) for rr in range(r,r+h) for cc in range(c,c+w))
      if cells <= mask: ps.append((r,c,cells))
  placements[name]=ps
print({k:len(v) for k,v in placements.items()})

coords=sorted(mask); idx={p:i for i,p in enumerate(coords)}
full=sum(1<<i for i in range(len(coords)))
type_names=list(piece_types)
rem0=tuple(piece_types[k][2] for k in type_names)
plms={}
plcover={}
for name,ps in placements.items():
  plms[name]=[(r,c,sum(1<<idx[p] for p in cells)) for r,c,cells in ps]
  for i,(r,c,bits) in enumerate(plms[name]):
    for p in placements[name][i][2]: plcover.setdefault(idx[p],[]).append((name,r,c,bits))
print(type_names, rem0, len(coords),sum(x[2] for x in piece_types.values()))

import functools, time
areas={name:piece_types[name][0]*piece_types[name][1] for name in type_names}
byidx={i:[] for i in range(len(coords))}
for name,plist in plms.items():
  for r,c,bits in plist:
    b=bits
    while b:
      low=b&-b; j=low.bit_length()-1; byidx[j].append((name,r,c,bits)); b-=low
# quick sorted use big pieces first
order={name:i for i,name in enumerate(type_names)}
for i in byidx: byidx[i].sort(key=lambda q:(-areas[q[0]],order[q[0]],q[1],q[2]))
solutions=[]; nodes=0; dead=set()
limit=25

def solve(uncovered,remaining,path):
  global nodes
  nodes+=1
  if not uncovered:
    if not any(remaining): solutions.append(path.copy())
    return len(solutions)>=limit
  if sum(remaining)==0: return False
  if sum(areas[n]*remaining[i] for i,n in enumerate(type_names)) != uncovered.bit_count(): return False
  key=(uncovered,remaining)
  if key in dead: return False
  # choose uncovered cell with fewest current placements
  b=uncovered; bestopts=None
  while b:
    low=b&-b; j=low.bit_length()-1; b-=low
    opts=[]
    for name,r,c,pbits in byidx[j]:
      ti=order[name]
      if remaining[ti] and (pbits & uncovered)==pbits: opts.append((name,r,c,pbits))
    if bestopts is None or len(opts)<len(bestopts):
      bestopts=opts
      if len(bestopts)<=1: break
  if not bestopts:
    dead.add(key); return False
  # branch by options sorted area desc and type counts
  for name,r,c,pbits in bestopts:
    ti=order[name]
    rem=list(remaining); rem[ti]-=1
    path.append((name,r,c))
    stop=solve(uncovered ^ pbits,tuple(rem),path)
    path.pop()
    if stop:return True
  dead.add(key); return False
start=time.time(); solve(full,rem0,[]); print('nodes',nodes,'sols',len(solutions),'dead',len(dead),'sec',time.time()-start)
for si,s in enumerate(solutions[:3]): print('\nSOL',si, s)
